//
//  prune-dist.ts
//  CV Hub — remove build-time YAML from a built `dist/`.
//
//  `astro build` copies `public/` verbatim, so every YAML the build *reads as
//  input* also lands in `dist/` and therefore in the image:
//
//    public/cv/<lang>.yaml                  generated by `cv:build` (merge.mjs)
//    public/media/projects/<slug>/*.yaml    project case studies
//
//  Nothing in the built site links to them — they are read at build time, page
//  by page, before anything is served — so shipping them is dead weight and
//  leaves them publicly reachable for no reason.
//
//  Usage:
//    node src/scripts/prune-dist.ts            # delete them, report the count
//    node src/scripts/prune-dist.ts --check    # exit 1 if any are present
//
//  `npm run build` runs the prune; CI's validate job runs `--check` against the
//  freshly built `dist/`, so a YAML that creeps back fails the pipeline rather
//  than slipping into a release.
//

import { existsSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '../..');

const YAML_RE = /\.ya?ml$/i;

/**
 * Every `.yaml`/`.yml` under `root`, as `/`-separated paths relative to `root`
 * and sorted for stable output. A missing `root` is an empty list, not an error.
 */
export function findYamlFiles(root: string): string[] {
  if (!existsSync(root)) return [];

  const out: string[] = [];
  const walk = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.isFile() && YAML_RE.test(entry.name)) {
        out.push(relative(root, full).split(sep).join('/'));
      }
    }
  };
  walk(root);

  return out.sort();
}

/**
 * Find the build-time YAML in `root`. Deletes it unless `check` is set, in
 * which case it is only reported. Returns the paths either way.
 */
export function pruneDistYaml(root: string, { check = false } = {}): string[] {
  const files = findYamlFiles(root);
  if (!check) {
    for (const rel of files) rmSync(join(root, rel), { force: true });
  }
  return files;
}

export function main(argv: string[] = process.argv.slice(2)): number {
  const check = argv.includes('--check');
  const dist = join(repoRoot, 'dist');
  const files = pruneDistYaml(dist, { check });

  if (check) {
    if (files.length === 0) {
      console.log('✔ dist/ carries no build-time YAML');
      return 0;
    }
    for (const rel of files) console.error(`  ❌ dist/${rel}`);
    console.error(`❌ ${files.length} build-time YAML file(s) in dist/ — the prune step is missing or ran too early`);
    return 1;
  }

  console.log(
    files.length === 0
      ? '✔ dist/: no build-time YAML to prune'
      : `✔ pruned ${files.length} build-time YAML file(s) from dist/`,
  );
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exit(main());
}
